def priority(task, state, c=2.0, boost=1e6):
    e = max(task.estimated_runtime, 1e-6)
    ratio = (state.now - task.release) / e
    return (boost if ratio >= c else 0.0) - e  # tuned (c=5.39,boost=3.33e+05)

import math
def priority(task, state, c=2.0, g=1e9, a=0.0, rho=1.0):
    est = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    if wait >= c * est:
        return g + 1.0 / est
    factor = 1.0 + a / (need ** rho)
    return (1.0 / est) * max(factor, 1e-6)  # tuned (c=1.39,g=3.36e+08,a=0,rho=1.56)
